def sum_digits(n):
    s = 0
    while n:
        s += n % 10
        n //= 10
    return s

def check_n(n):
    # We need to check S(n) through S(n+37)
    for i in range(38):
        m = n + i
        s_m = sum_digits(m)
        if s_m % 11 == 0:
            # Found a factor that is a multiple of 11
            return False # Condition failed for this n

    # All 38 factors are not multiples of 11
    return True # Condition met for this n

# Start searching from n=1
n = 1
while True:
    if check_n(n):
        print(f"Found smallest n: {n}")
        break
    n += 1
